fn parse(s: &str) -> Result<i32, std::num::ParseIntError> { s.parse::<i32>() }
match parse("42") {
    Ok(n) => println!("got {n}"),
    Err(e) => println!("error: {e}"),
}

fn read_number(s: &str) -> Result<i32, std::num::ParseIntError> {
    let n = s.parse::<i32>()?; // при Err функция сразу вернёт этот Err
    Ok(n * 2)
}

