trait Animal {
    fn name(&self) -> String;
    fn sound(&self) -> String;
    fn describe(&self) -> String { format!("{} говорит {}", self.name(), self.sound()) }
}
struct Dog;
impl Animal for Dog {
    fn name(&self) -> String { "Пёс".into() }
    fn sound(&self) -> String { "гав".into() }
}

fn print_static<T: Animal>(a: &T) { println!("{}", a.describe()); } // static
let zoo: Vec<Box<dyn Animal>> = vec![Box::new(Dog)];                 // dynamic
for a in &zoo { println!("{}", a.describe()); }

fn largest<T: PartialOrd>(list: &[T]) -> &T {
    let mut max = &list[0];
    for x in list { if x > max { max = x; } }
    max
}

